mapper.select:
SELECT COALESCE(SUM(refund_amount), 0)
FROM cancellation_records
WHERE sale_record_id = #{saleRecordId}

SELECT id, sale_record_id, refund_amount, canceled_at
FROM cancellation_records
WHERE canceled_at >= #{from} AND canceled_at < #{to}

SELECT cr.id, cr.sale_record_id, cr.refund_amount, cr.canceled_at
FROM cancellation_records cr
JOIN sale_records sr ON cr.sale_record_id = sr.id
JOIN courses c ON sr.course_id = c.id
WHERE c.creator_id = #{creatorId}
  AND cr.canceled_at >= #{from}
  AND cr.canceled_at < #{to}
